function d_sir(P,R){var S=P.S||990,I=P.I||10,Rc=0,N=S+I,beta=P.beta||0.3,gamma=P.gamma||0.1,days=P.days||60;var peak=I;for(var d=0;d<days;d++){var ni=beta*S*I/N,rec=gamma*I;S-=ni;I+=ni-rec;Rc+=rec;if(I>peak)peak=I;}return{days:days,peak_infected:Math.round(peak),final_recovered:Math.round(Rc),R0:+(beta/gamma).toFixed(2)};}

